hudson.tasks.Shell.command:
#!/bin/bash mkdir ${STUDY_ID}.${DATASET_NAME} cd ${STUDY_ID}.${DATASET_NAME} dbname="${DATASET_NAME,,}_${VERSION,,}" conn_user='postgres' conn_pass=`aws secretsmanager get-secret-value --secret-id 'rds!db-2b115560-c8c4-4cec-8418-537a35f9c192' --region 'us-east-1' --query SecretString --output text | jq -r .password` database_psql_host_address='recoverdb.cljahwnkfisu.us-east-1.rds.amazonaws.com' PGPASSWORD="$conn_pass" psql --host="$database_psql_host_address" --port="5432" --username="$conn_user" --dbname="${dbname}" --csv -Atc "select quote_ident(schemaname) || '.' || quote_ident(tablename) from pg_tables where schemaname~'^output'" |\ while read TBL; do PGPASSWORD="$conn_pass" psql --quiet --host="recoverdb.cljahwnkfisu.us-east-1.rds.amazonaws.com" \ --port="5432" \ --dbname="${dbname}" \ -U $conn_user -c "\COPY (select dbgap_subject_id, * from $TBL left join (select \"SUBJECT_ID\" as subject_id, dbgap_subject_id from resources.telemetry_report) as telemetry on telemetry.subject_id = $TBL.participant_id) TO ./${STUDY_ID}.${DATASET_NAME}_${VERSION}.$TBL.csv with (FORMAT CSV, HEADER TRUE, FORCE_QUOTE *)" & echo Copying "${STUDY_ID}.${DATASET_NAME}.$TBL.csv" done wait; aws sts assume-role --duration-seconds 3600 --role-arn arn:aws:iam::736265540791:role/dbgap-etl --role-session-name "s3-test" > assume-role-output.txt
export AWS_ACCESS_KEY_ID=`grep AccessKeyId assume-role-output.txt | cut -d ':' -f 2 | sed "s/[ ,\"]//g"` export AWS_SECRET_ACCESS_KEY=`grep SecretAccessKey assume-role-output.txt | cut -d ':' -f 2 | sed "s/[ ,\"]//g"` export AWS_SESSION_TOKEN=`grep SessionToken assume-role-output.txt | cut -d ':' -f 2 | sed "s/[ ,\"]//g"` rm -f assume-role-output.txt
aws s3 cp . s3://avillach-73-bdcatalyst-etl/${STUDY_ABV,,}/decoded_data/ --recursive --exclude "*" --include "*.csv"
